class ScriptedModel:
    def __init__(self, turns):
        self.turns = list(turns)
    def complete(self, messages):
        return self.turns.pop(0)

def run_agent(model, user_text, max_steps=5):
    """Loop: ask the model, dispatch tool calls, stop on final_answer."""
    messages = [{"role": "user", "content": user_text}]
    for step in range(1, max_steps + 1):
        turn = model.complete(messages)
        messages.append({"role": "assistant", **turn})
        if "final_answer" in turn:
            return turn["final_answer"], len(messages)
        result = dispatch(turn["tool_call"], TOOLS)
        messages.append({"role": "tool", "content": str(result)})
    return "stopped: step limit reached", len(messages)

model = ScriptedModel([
    {"tool_call": {"name": "add", "args": {"a": 20, "b": 22}}},
    {"tool_call": {"name": "shout", "args": {"text": "forty-two"}}},
    {"final_answer": "FORTY-TWO!"},
])
answer, n = run_agent(model, "Add 20 and 22, then shout it.")
print(answer)
print(n)
